import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-06-25","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-06-25","date":"2025-06-25T00:00:00.000Z","updated":"2025-07-09T00:00:00.000Z","tags":["Ceph","RGW","SSE-C","CLS Hash 优化","Blake3"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-06-25.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-06-25.md","lastUpdated":1780460162000}'),o={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-06-25.md"};function n(s,a,i,g,h,_){return e(),r("div",null,[...a[0]||(a[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>日期</strong>: 2025-06-25 | <strong>主持人</strong>: （主持人名称未提供）</p><h4 id="_1-会议主题与讨论重点" tabindex="-1">1. 会议主题与讨论重点 <a class="header-anchor" href="#_1-会议主题与讨论重点" aria-label="Permalink to &quot;1. 会议主题与讨论重点&quot;">​</a></h4><p>本次会议围绕 Ceph 分布式存储的 RGW 优化议题展开，主要讨论了以下内容：</p><ul><li><strong>SSE-C 头部验证问题</strong>：针对多部分上传（multipart upload）的测试用例失败问题，团队决定推迟修复至后续版本。</li><li><strong>CLS Hash 优化</strong>： <ul><li><strong>Gabby</strong> 提出在 OSD 端计算 CLS 哈希（支持 MD5/SHA-256/Blake3），以减少 RGW 的数据传输负载。</li><li>讨论了 Blake3 状态序列化问题，提出了两种方案： <ul><li><strong>静态断言（static assert）</strong>：锁定子模块版本，禁止不兼容升级。</li><li><strong>动态检查（dynamic check）</strong>：运行时验证 Blake3 数据结构，失败时回退到本地计算。</li></ul></li><li>团队倾向于动态检查方案，并计划联系 Blake3 维护者寻求官方序列化支持。</li></ul></li></ul><h4 id="_2-关键决议" tabindex="-1">2. 关键决议 <a class="header-anchor" href="#_2-关键决议" aria-label="Permalink to &quot;2. 关键决议&quot;">​</a></h4><ul><li><strong>SSE-C 问题</strong>：暂不合并当前 PR，等待进一步测试后纳入后续版本。</li><li><strong>CLS Hash 优化</strong>： <ul><li><strong>通过动态检查实现 Blake3 状态传递</strong>，失败时自动回退到传统模式。</li><li><strong>探索 Blake3 官方序列化 API</strong>，以长期解决数据结构依赖问题。</li><li><strong>支持在对象属性中存储 Blake3 哈希值</strong>，增强未来增量去重（DDUP）的效率。</li></ul></li></ul><h4 id="_3-后续行动计划" tabindex="-1">3. 后续行动计划 <a class="header-anchor" href="#_3-后续行动计划" aria-label="Permalink to &quot;3. 后续行动计划&quot;">​</a></h4><p>| <strong>任务</strong> | <strong>负责人</strong> | <strong>时间节点</strong> | |-||--| | 提交 SSE-C 测试失败日志至 Marcus 的 PR | Cena | 立即 | | 完善 CLS Hash 动态检查逻辑，提交 PR | Gabby | 下周 | | 联系 Blake3 社区探讨序列化支持 | Gabby/Matt | 两周内 | | 评估静态断言替代方案（如 C++23 结构检查） | Matt | 待定 |</p><h4 id="_4-其他事项" tabindex="-1">4. 其他事项 <a class="header-anchor" href="#_4-其他事项" aria-label="Permalink to &quot;4. 其他事项&quot;">​</a></h4><ul><li><strong>S3 对象所有权功能</strong>：Matt 新推的功能（禁用对象 ACLs），鼓励社区测试反馈。</li><li><strong>哈希算法扩展</strong>：未来可能支持 CRC64 或 XXH3 作为补充，但需确保 Blake3 的加密强度优先。</li></ul><h4 id="_5-会议结论" tabindex="-1">5. 会议结论 <a class="header-anchor" href="#_5-会议结论" aria-label="Permalink to &quot;5. 会议结论&quot;">​</a></h4><p>会议决定在确保安全回退机制的前提下，推进 CLS Hash 优化，并探索更健壮的 Blake3 集成方案。</p><p>通过以上分析和改进，确保了总结内容准确反映了会议的关键细节，并保留了 Ceph 相关领域的英文原文关键词。</p>',14)])])}const d=t(o,[["render",n]]);export{c as __pageData,d as default};
